import ast
import contextlib
import importlib
import json
from pathlib import Path
from typing import Any

import pandas as pd
from langchain_experimental.utilities import PythonREPL

from langflow.custom.custom_component.component import Component
from langflow.io import BoolInput, CodeInput, FileInput, Output, StrInput
from langflow.schema.data import Data


class CSVPythonREPLComponent(Component):
    display_name = "CSV Python Interpreter"
    description = (
        "Run Python code against an ingested CSV dataframe. "
        "The CSV is loaded into pandas and exposed as `df`."
    )
    documentation: str = "https://docs.langflow.org/components-processing#python-interpreter"
    icon = "square-terminal"
    name = "CSVPythonREPL"

    inputs = [
        FileInput(
            name="csv_file",
            display_name="CSV File",
            file_types=["csv"],
            input_types=["str", "Message"],
            required=True,
            info="CSV file or file path to load into pandas as `df`.",
        ),
        StrInput(
            name="global_imports",
            display_name="Global Imports",
            info=(
                "Comma-separated modules to import globally. "
                "Examples: 'math,pandas,json,ast' or 'pandas as pd'. "
                "Note: pandas is always available as `pd` and `pandas`."
            ),
            value="math,pandas,json,ast",
            required=True,
        ),
        StrInput(
            name="read_csv_kwargs",
            display_name="pandas.read_csv Kwargs",
            info=(
                "Optional JSON or Python dict string passed to pandas.read_csv. "
                "Example: {\"encoding\": \"utf-8\"}"
            ),
            value="{}",
            advanced=True,
        ),
        BoolInput(
            name="persist_runtime",
            display_name="Persist Python Runtime",
            info=(
                "Keep the same Python REPL globals across calls. "
                "This lets the agent define helper variables/functions and reuse them."
            ),
            value=True,
            advanced=True,
        ),
        BoolInput(
            name="reset_dataframe_each_run",
            display_name="Reset DataFrame Each Run",
            info=(
                "Reset `df` from the original CSV before each code execution. "
                "Recommended for reliability so accidental dataframe mutations do not persist."
            ),
            value=True,
            advanced=True,
        ),
        CodeInput(
            name="python_code",
            display_name="Python Code",
            info=(
                "Python code to execute. The CSV is available as `df`. "
                "Use print() to return output."
            ),
            value="print(df.head())",
            input_types=["Message"],
            tool_mode=True,
            required=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Results",
            name="results",
            type_=Data,
            method="run_python_repl",
        ),
    ]

    RELATIONSHIP_COLUMNS = [
        "PARENT_TACTICS",
        "PARENT_TECHNIQUES",
        "PARENT_MITIGATIONS",
        "PARENT_CASESTUDIES",
        "CHILD_TECHNIQUES",
    ]

    RESERVED_GLOBALS = {
        "df",
        "pd",
        "pandas",
        "_df_original",
        "_df_source",
        "_df_shape",
        "_df_columns",
        "RELATIONSHIP_COLUMNS",
        "parse_relationship",
        "parse_ids",
        "hydrate_ids",
        "records",
        "json_ready",
    }

    def _coerce_text(self, value: Any) -> str:
        """Convert Langflow Message-like values or plain strings into text."""
        if value is None:
            return ""

        if isinstance(value, str):
            return value

        if hasattr(value, "text") and isinstance(value.text, str):
            return value.text

        if hasattr(value, "data") and isinstance(value.data, dict):
            for key in ("text", "path", "file_path", "csv_file"):
                if key in value.data and value.data[key]:
                    return str(value.data[key])

        return str(value)

    def _get_csv_path(self) -> str:
        """Resolve CSV input into a path/string usable by pandas.read_csv."""
        value = getattr(self, "csv_file", None)

        if value is None:
            msg = "No CSV file was provided."
            raise ValueError(msg)

        if isinstance(value, list):
            if not value:
                msg = "CSV file input was an empty list."
                raise ValueError(msg)
            value = value[0]

        if isinstance(value, str):
            return value

        if hasattr(value, "text") and isinstance(value.text, str):
            return value.text

        if hasattr(value, "path"):
            return str(value.path)

        if hasattr(value, "data") and isinstance(value.data, dict):
            for key in ("path", "file_path", "csv_file", "source"):
                if key in value.data and value.data[key]:
                    return str(value.data[key])

        return str(value)

    def _parse_read_csv_kwargs(self) -> dict:
        """Parse read_csv kwargs from JSON/Python dict string."""
        raw = getattr(self, "read_csv_kwargs", None)

        if raw is None or raw == "":
            return {}

        if isinstance(raw, dict):
            return raw

        text = str(raw).strip()
        if not text:
            return {}

        try:
            parsed = json.loads(text)
        except Exception:
            try:
                parsed = ast.literal_eval(text)
            except Exception as e:
                msg = f"read_csv_kwargs must be a JSON object or Python dict string: {e!s}"
                raise ValueError(msg) from e

        if not isinstance(parsed, dict):
            msg = "read_csv_kwargs must parse to a dictionary."
            raise ValueError(msg)

        return parsed

    def _load_dataframe(self) -> pd.DataFrame:
        """Load the CSV into a pandas DataFrame."""
        csv_path = self._get_csv_path()
        read_csv_kwargs = self._parse_read_csv_kwargs()

        try:
            df = pd.read_csv(csv_path, **read_csv_kwargs)
        except Exception as e:
            msg = f"Failed to load CSV with pandas.read_csv from {csv_path!r}: {e!s}"
            raise ValueError(msg) from e

        return df

    def _runtime_key(self) -> tuple:
        """Create a cache key so the runtime refreshes when the CSV/config changes."""
        csv_path = self._get_csv_path()
        read_csv_kwargs = self._parse_read_csv_kwargs()
        global_imports = getattr(self, "global_imports", "")

        path_fingerprint: Any = csv_path

        with contextlib.suppress(Exception):
            path_obj = Path(csv_path)
            if path_obj.exists():
                stat = path_obj.stat()
                path_fingerprint = (
                    str(path_obj.resolve()),
                    stat.st_mtime_ns,
                    stat.st_size,
                )

        return (
            path_fingerprint,
            json.dumps(read_csv_kwargs, sort_keys=True, default=str),
            str(global_imports),
        )

    def get_globals(self, global_imports: str | list[str]) -> dict:
        """Create a globals dictionary with the specified imports."""
        global_dict = {}

        try:
            if isinstance(global_imports, str):
                modules = [module.strip() for module in global_imports.split(",") if module.strip()]
            elif isinstance(global_imports, list):
                modules = [str(module).strip() for module in global_imports if str(module).strip()]
            else:
                msg = "global_imports must be either a string or a list."
                raise TypeError(msg)

            for module_spec in modules:
                module_name = module_spec
                alias = None

                if " as " in module_spec:
                    module_name, alias = [part.strip() for part in module_spec.split(" as ", 1)]

                imported_module = importlib.import_module(module_name)

                canonical_name = imported_module.__name__
                global_dict[canonical_name] = imported_module

                if alias:
                    global_dict[alias] = imported_module

                if canonical_name == "pandas":
                    global_dict["pd"] = imported_module
                    global_dict["pandas"] = imported_module

                if canonical_name == "numpy":
                    global_dict["np"] = imported_module
                    global_dict["numpy"] = imported_module

        except Exception as e:
            self.log(f"Error in global imports: {e!s}")
            raise

        self.log(f"Successfully imported modules: {sorted(global_dict.keys())}")
        return global_dict

    def _install_dataframe_helpers(self, globals_: dict) -> None:
        """Install dataframe helper functions into the REPL globals."""

        relationship_columns = list(self.RELATIONSHIP_COLUMNS)

        def _is_missing_scalar(value: Any) -> bool:
            if value is None:
                return True

            if isinstance(value, float):
                return bool(pd.isna(value))

            try:
                result = pd.isna(value)
            except Exception:
                return False

            if isinstance(result, bool):
                return result

            return False

        def parse_relationship(value: Any) -> list[str]:
            """Parse ATLAS relationship fields into a clean list of string IDs."""
            if _is_missing_scalar(value):
                return []

            if isinstance(value, list | tuple | set):
                return [str(item).strip() for item in value if str(item).strip()]

            text = str(value).strip()

            if text == "" or text in {"[]", "null", "None", "nan", "NaN"}:
                return []

            try:
                parsed = ast.literal_eval(text)
                if parsed is None:
                    return []
                if isinstance(parsed, list | tuple | set):
                    return [str(item).strip() for item in parsed if str(item).strip()]
                if isinstance(parsed, str):
                    parsed_text = parsed.strip()
                    return [parsed_text] if parsed_text else []
            except Exception:
                pass

            if "," in text:
                return [part.strip() for part in text.split(",") if part.strip()]

            return [text]

        def parse_ids(value: Any) -> list[str]:
            """Parse a single ID, comma-separated IDs, newline IDs, list, or {'ids': [...]}."""
            if value is None:
                return []

            if isinstance(value, dict):
                value = value.get("ids", [])

            if isinstance(value, list | tuple | set):
                ids = []
                for item in value:
                    ids.extend(parse_ids(item))
                return ids

            text = str(value).strip()
            if not text:
                return []

            try:
                parsed = ast.literal_eval(text)
                if isinstance(parsed, dict):
                    return parse_ids(parsed)
                if isinstance(parsed, list | tuple | set):
                    return parse_ids(list(parsed))
            except Exception:
                pass

            pieces = []
            for line in text.splitlines():
                pieces.extend(line.split(","))

            return [piece.strip().strip("'\"") for piece in pieces if piece.strip().strip("'\"")]

        def json_ready(value: Any) -> Any:
            """Convert pandas/numpy values into JSON-compatible Python objects."""
            if value is None:
                return None

            if isinstance(value, pd.DataFrame):
                return records(value)

            if isinstance(value, pd.Series):
                return json_ready(value.to_dict())

            if isinstance(value, dict):
                return {str(k): json_ready(v) for k, v in value.items()}

            if isinstance(value, list | tuple | set):
                return [json_ready(item) for item in value]

            if _is_missing_scalar(value):
                return None

            if hasattr(value, "item"):
                try:
                    return value.item()
                except Exception:
                    pass

            return value

        def records(frame: Any = None, parse_relationships: bool = True) -> list[dict]:
            """
            Convert a dataframe to JSON-compatible records.

            By default, known ATLAS relationship columns are parsed into lists.
            """
            if frame is None:
                frame = globals_["df"]

            if isinstance(frame, pd.Series):
                frame = frame.to_frame().T

            if not isinstance(frame, pd.DataFrame):
                return json_ready(frame)

            out = frame.copy()

            if parse_relationships:
                for column in relationship_columns:
                    if column in out.columns:
                        out[column] = out[column].apply(parse_relationship)

            raw_records = out.to_dict(orient="records")
            return json_ready(raw_records)

        def hydrate_ids(ids: Any, frame: Any = None) -> dict:
            """
            Hydrate one or more AML IDs from the current dataframe.

            Returns:
            {
                "records": [...],
                "missing_ids": [...]
            }
            """
            if frame is None:
                frame = globals_["df"]

            wanted_ids = parse_ids(ids)

            if "id" not in frame.columns:
                return {
                    "records": [],
                    "missing_ids": wanted_ids,
                    "error": "Current dataframe does not contain an 'id' column.",
                }

            id_series = frame["id"].astype(str)
            matched = frame[id_series.isin(wanted_ids)].copy()

            found_ids = set(matched["id"].astype(str).tolist())
            missing_ids = [item for item in wanted_ids if item not in found_ids]

            return {
                "records": records(matched),
                "missing_ids": missing_ids,
            }

        globals_["RELATIONSHIP_COLUMNS"] = relationship_columns
        globals_["parse_relationship"] = parse_relationship
        globals_["parse_ids"] = parse_ids
        globals_["json_ready"] = json_ready
        globals_["records"] = records
        globals_["hydrate_ids"] = hydrate_ids

    def _build_runtime_globals(self) -> dict:
        """Build the REPL globals and inject the CSV dataframe."""
        globals_ = self.get_globals(self.global_imports)

        # pandas is always available, even if omitted from global_imports.
        globals_["pd"] = pd
        globals_["pandas"] = pd

        source = self._get_csv_path()
        loaded_df = self._load_dataframe()

        # Store a pristine copy so `df` can be reset between calls.
        globals_["_df_original"] = loaded_df.copy(deep=True)
        globals_["df"] = loaded_df.copy(deep=True)

        globals_["_df_source"] = source
        globals_["_df_shape"] = tuple(loaded_df.shape)
        globals_["_df_columns"] = list(loaded_df.columns)

        self._install_dataframe_helpers(globals_)

        return globals_

    def _reset_dataframe(self) -> None:
        """Reset `df` from `_df_original` while preserving the rest of the runtime."""
        globals_ = getattr(self, "_runtime_globals", None)
        if not globals_:
            return

        original = globals_.get("_df_original")
        if isinstance(original, pd.DataFrame):
            globals_["df"] = original.copy(deep=True)
            globals_["_df_shape"] = tuple(globals_["df"].shape)
            globals_["_df_columns"] = list(globals_["df"].columns)

    def _get_repl(self) -> PythonREPL:
        """
        Get or create the PythonREPL.

        If persist_runtime=True, the same REPL/globals are reused unless the CSV/config changes.
        If reset_dataframe_each_run=True, `df` is refreshed from `_df_original` before each execution.
        """
        key = self._runtime_key()
        persist_runtime = bool(getattr(self, "persist_runtime", True))
        reset_dataframe_each_run = bool(getattr(self, "reset_dataframe_each_run", True))

        should_rebuild = (
            not persist_runtime
            or not hasattr(self, "_python_repl")
            or not hasattr(self, "_runtime_key_cache")
            or self._runtime_key_cache != key
        )

        if should_rebuild:
            self._runtime_globals = self._build_runtime_globals()
            self._python_repl = PythonREPL(_globals=self._runtime_globals)
            self._runtime_key_cache = key
            self.log(
                "Initialized CSV Python runtime with "
                f"shape={self._runtime_globals['_df_shape']} "
                f"columns={self._runtime_globals['_df_columns']}"
            )
        elif reset_dataframe_each_run:
            self._reset_dataframe()

        return self._python_repl

    def run_python_repl(self) -> Data:
        try:
            python_repl = self._get_repl()
            code = self._coerce_text(self.python_code)

            result = python_repl.run(code)
            result = result.strip() if result else ""

            self.log("Code execution completed successfully")

            return Data(
                data={
                    "result": result,
                    "dataframe": {
                        "name": "df",
                        "source": getattr(self, "_runtime_globals", {}).get("_df_source"),
                        "shape": getattr(self, "_runtime_globals", {}).get("_df_shape"),
                        "columns": getattr(self, "_runtime_globals", {}).get("_df_columns"),
                    },
                }
            )

        except ImportError as e:
            error_message = f"Import Error: {e!s}"
            self.log(error_message)
            return Data(data={"error": error_message})

        except SyntaxError as e:
            error_message = f"Syntax Error: {e!s}"
            self.log(error_message)
            return Data(data={"error": error_message})

        except Exception as e:
            error_message = f"Error during execution: {e!s}"
            self.log(error_message)
            return Data(data={"error": error_message})

    def build(self):
        return self.run_python_repl
